import { type ReactNode } from 'react';
import { useSidebar } from './SidebarContext';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export type SidebarProps = {
  side?: 'left' | 'right';
  children: ReactNode;
  className?: string;
};

export function Sidebar({ side = 'left', children, className }: SidebarProps) {
  const { collapsed } = useSidebar();
  return (
    <aside
      data-sidebar=""
      className={cn(
        'sidebar',
        collapsed && 'sidebar--collapsed',
        side === 'right' && 'sidebar--right',
        className,
      )}
    >
      {children}
    </aside>
  );
}

import { createContext, useContext, useState, useCallback, type ReactNode } from 'react';

type SidebarContextValue = {
  collapsed: boolean;
  toggle: () => void;
  setCollapsed: (v: boolean) => void;
};

const SidebarContext = createContext<SidebarContextValue | null>(null);

export function useSidebar() {
  const ctx = useContext(SidebarContext);
  if (!ctx) throw new Error('useSidebar must be used within SidebarProvider');
  return ctx;
}

export function SidebarProvider({
  defaultCollapsed = false,
  children,
}: {
  defaultCollapsed?: boolean;
  children: ReactNode;
}) {
  const [collapsed, setCollapsed] = useState(defaultCollapsed);
  const toggle = useCallback(() => setCollapsed((v) => !v), []);

  return (
    <SidebarContext.Provider value={{ collapsed, toggle, setCollapsed }}>
      {children}
    </SidebarContext.Provider>
  );
}

import { type ReactNode } from 'react';

export function SidebarHeader({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={`sidebar__header ${className || ''}`}>{children}</div>;
}

import { type ReactNode } from 'react';

export function SidebarContent({ children, className }: { children: ReactNode; className?: string }) {
  return <nav className={`sidebar__content ${className || ''}`}>{children}</nav>;
}

import { type ReactNode } from 'react';

export function SidebarFooter({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={`sidebar__footer ${className || ''}`}>{children}</div>;
}

import { type ReactNode } from 'react';

export function SidebarGroup({ label, children, className }: { label?: string; children: ReactNode; className?: string }) {
  return (
    <div className={`sidebar__group ${className || ''}`}>
      {label && <span className="sidebar__group-label" data-sidebar-group-label="">{label}</span>}
      {children}
    </div>
  );
}

import { type ReactNode, type AnchorHTMLAttributes } from 'react';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export type SidebarItemProps = {
  icon: ReactNode;
  label: string;
  badge?: string;
  active?: boolean;
  disabled?: boolean;
  className?: string;
} & Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children'>;

export function SidebarItem({
  icon,
  label,
  badge,
  active = false,
  disabled = false,
  className,
  ...props
}: SidebarItemProps) {
  const classes = cn(
    'sidebar__item',
    active && 'sidebar__item--active',
    disabled && 'sidebar__item--disabled',
    className,
  );

  return (
    <a data-sidebar-item="" data-tooltip={label} className={classes} aria-current={active ? 'page' : undefined} aria-disabled={disabled || undefined} {...props}>
      <span className="sidebar__item-icon">{icon}</span>
      <span className="sidebar__item-label" data-sidebar-label="">{label}</span>
      {badge && <span className="sidebar__item-badge" data-sidebar-label="">{badge}</span>}
    </a>
  );
}

import { useState, type ReactNode } from 'react';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

const ChevronDown = () => (
  <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M4 6l4 4 4-4" />
  </svg>
);

export type SidebarCollapsibleProps = {
  icon: ReactNode;
  label: string;
  defaultOpen?: boolean;
  children: ReactNode;
  className?: string;
};

export function SidebarCollapsible({
  icon,
  label,
  defaultOpen = false,
  children,
  className,
}: SidebarCollapsibleProps) {
  const [open, setOpen] = useState(defaultOpen);

  return (
    <div className={cn('sidebar-collapsible', open && 'sidebar-collapsible--open', className)}>
      <button
        type="button"
        className="sidebar-collapsible__trigger"
        data-tooltip={label}
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
      >
        <span className="sidebar__item-icon">{icon}</span>
        <span className="sidebar-collapsible__label" data-sidebar-label="">{label}</span>
        <span className="sidebar-collapsible__chevron" data-sidebar-chevron="">
          <ChevronDown />
        </span>
      </button>
      <div className="sidebar-collapsible__content">
        <div className="sidebar-collapsible__inner">
          {children}
        </div>
      </div>
    </div>
  );
}

import { useSidebar } from './SidebarContext';

const CircleChevronLeft = () => (
  <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="8" cy="8" r="6" />
    <path d="M9.25 5.5L6.75 8l2.5 2.5" />
  </svg>
);

const CircleChevronRight = () => (
  <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
    <circle cx="8" cy="8" r="6" />
    <path d="M6.75 5.5L9.25 8l-2.5 2.5" />
  </svg>
);

export function SidebarTrigger({ className }: { className?: string }) {
  const { collapsed, toggle } = useSidebar();

  return (
    <button
      type="button"
      data-sidebar-trigger=""
      className={`sidebar__trigger ${className || ''}`}
      onClick={toggle}
      aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
    >
      {collapsed ? <CircleChevronRight /> : <CircleChevronLeft />}
    </button>
  );
}

/* -------------------------------------------------------------------------
   Sidebar

   Composable: Provider (state) + Container + Header/Content/Footer
   Collapse: .sidebar--collapsed toggles layout via CSS
   Labels: [data-sidebar-label] hidden in collapsed via display:none
   Tooltips: [data-tooltip] from tooltip.css, overridden to right/light
   Animations: scale on hover, icon rotation in collapsed

   240px expanded, 48px collapsed. Semantic tokens for colors.
   ------------------------------------------------------------------------- */

/* ---- Container ---- */

.sidebar {
  --sidebar-w: 240px;
  --sidebar-w-collapsed: 48px;

  display: flex;
  flex-direction: column;
  width: var(--sidebar-w);
  height: 100%;
  min-height: 100%;
  background: var(--sidebar-bg);
  border-right: 1px solid var(--sidebar-border);
  flex-shrink: 0;
  transition: width 0.3s cubic-bezier(0.19, 1, 0.22, 1);
}

.sidebar--collapsed { width: var(--sidebar-w-collapsed); }

/* ---- Sections ---- */

.sidebar__header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 12px;
  flex-shrink: 0;
}

.sidebar__content {
  flex: 1;
  overflow-y: auto;
  padding: 8px;
}

.sidebar__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px;
  flex-shrink: 0;
  margin-top: auto;
  border-top: 1px solid var(--sidebar-border);
}

.sidebar__divider {
  border: none;
  border-top: 1px solid var(--border);
  margin: 8px 0;
}

/* Collapsed sections */
.sidebar--collapsed .sidebar__header { flex-direction: column; gap: 8px; padding: 8px; align-items: center; }
.sidebar--collapsed .sidebar__content { overflow: visible; padding: 4px; }
.sidebar__footer .dropdown-menu { width: 100%; }
.sidebar__footer .dropdown-menu__trigger { width: 100%; }
.sidebar__footer .dropdown-menu__content { width: 100%; }

.sidebar--collapsed .sidebar__footer { padding: 8px; justify-content: center; }

/* ---- Labels: hide in collapsed ---- */

.sidebar--collapsed [data-sidebar-label] { display: none; }

/* ---- Group ---- */

.sidebar__group { display: flex; flex-direction: column; gap: 2px; }
.sidebar__group + .sidebar__group { margin-top: 24px; }

.sidebar__group-label {
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-xs);
  font-weight: var(--font-weight-medium);
  color: var(--muted-foreground);
  padding: 4px 8px;
  text-transform: uppercase;
  letter-spacing: var(--letter-spacing-wide);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar--collapsed .sidebar__group-label { display: none; }

/* ---- Item ---- */

.sidebar__item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px;
  height: 36px;
  border-radius: 6px;
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  color: var(--foreground);
  text-decoration: none;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
  transition:
    background-color 0.15s cubic-bezier(0.19, 1, 0.22, 1),
    color 0.15s cubic-bezier(0.19, 1, 0.22, 1),
    scale 0.45s cubic-bezier(0.32, 0.72, 0, 1);
}

.sidebar__item:hover { background: var(--muted); color: var(--placeholder); }
.sidebar__item:active:not(.sidebar__item--disabled) { scale: 0.955 0.925; }
.sidebar__item--active { background: var(--sidebar-active); color: var(--sidebar-active-foreground); }
.sidebar__item--disabled { color: var(--muted-foreground); cursor: not-allowed; pointer-events: none; }

/* Item parts */
.sidebar__item-icon { display: flex; align-items: center; justify-content: center; flex-shrink: 0; width: 18px; height: 18px; transition: rotate 0.5s cubic-bezier(0.19, 1, 0.22, 1); }
.sidebar__item-icon svg { width: 100%; height: 100%; }
.sidebar__item-label { flex: 1; overflow: hidden; text-overflow: ellipsis; }
.sidebar__item-badge { font-size: var(--font-size-xs); font-weight: var(--font-weight-medium); color: var(--muted-foreground); flex-shrink: 0; }

/* Collapsed items: icon-only, centered */
.sidebar--collapsed .sidebar__item { justify-content: center; padding: 0; width: 32px; height: 32px; margin: 0 auto; }
.sidebar--collapsed .sidebar__item-label,
.sidebar--collapsed .sidebar__item-badge { display: none; }

/* ---- Hover animations ---- */

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  /* Expanded: subtle Button-style grow */
  .sidebar:not(.sidebar--collapsed) .sidebar__item:hover:not(.sidebar__item--disabled):not(.sidebar__item--active) {
    scale: 1.03 1.05;
  }
  /* Collapsed: IconButton-style scale + icon spin */
  .sidebar--collapsed .sidebar__item:hover:not(.sidebar__item--disabled):not(.sidebar__item--active) {
    scale: 1.095;
  }
  .sidebar--collapsed .sidebar__item:hover .sidebar__item-icon {
    rotate: 360deg;
    transition: rotate 0.6s 0.05s cubic-bezier(0.19, 1, 0.22, 1);
  }
}

/* ---- Trigger ---- */

.sidebar__trigger {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 4px;
  border: none;
  background: var(--muted);
  color: var(--muted-foreground);
  cursor: pointer;
  border-radius: 4px;
  flex-shrink: 0;
  transition: background-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.sidebar__trigger:hover { background: var(--border); color: var(--foreground); }
.sidebar__trigger svg { width: 16px; height: 16px; }

.sidebar--collapsed .sidebar__trigger { background: var(--sidebar-bg); color: var(--muted-foreground); box-shadow: var(--shadow-md); }
.sidebar--collapsed .sidebar__trigger:hover { background: var(--muted); color: var(--placeholder); }

/* ---- Tooltips (collapsed only) ---- */

.sidebar:not(.sidebar--collapsed) [data-tooltip]::before,
.sidebar:not(.sidebar--collapsed) [data-tooltip]::after { display: none !important; }

.sidebar--collapsed [data-tooltip]::before {
  bottom: auto !important; top: 50% !important;
  left: calc(100% + 10px) !important; right: auto !important;
  transform: translateY(-50%) translateX(-4px) !important;
  background: var(--background) !important; color: var(--foreground) !important;
  border: 1px solid var(--border) !important;
  box-shadow: 0 1px 3px rgb(0 0 0 / 0.1) !important;
}
.sidebar--collapsed [data-tooltip]:hover::before { transform: translateY(-50%) translateX(0) !important; }

.sidebar--collapsed [data-tooltip]::after {
  bottom: auto !important; top: 50% !important;
  left: calc(100% + 7px) !important; right: auto !important;
  transform: translateY(-50%) rotate(225deg) !important;
  background: var(--background) !important;
  border: 1px solid var(--border) !important;
  border-top: none !important; border-left: none !important;
}

/* ---- Collapsible ---- */

.sidebar-collapsible__trigger {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 8px;
  height: 36px;
  width: 100%;
  border: none;
  background: none;
  border-radius: 6px;
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  color: var(--foreground);
  cursor: pointer;
  user-select: none;
  text-align: left;
  white-space: nowrap;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.sidebar-collapsible__trigger:hover { background: var(--muted); }
.sidebar-collapsible__label { flex: 1; overflow: hidden; text-overflow: ellipsis; }
.sidebar-collapsible__chevron { display: flex; align-items: center; justify-content: center; flex-shrink: 0; color: var(--muted-foreground); transition: transform 0.2s ease; }

.sidebar-collapsible--open .sidebar-collapsible__chevron { transform: rotate(0deg); }
.sidebar-collapsible:not(.sidebar-collapsible--open) .sidebar-collapsible__chevron { transform: rotate(-90deg); }

/* Collapsible content: animated height */
.sidebar-collapsible__content { display: grid; grid-template-rows: 1fr; transition: grid-template-rows 0.25s cubic-bezier(0.19, 1, 0.22, 1); }
.sidebar-collapsible:not(.sidebar-collapsible--open) .sidebar-collapsible__content { grid-template-rows: 0fr; }
.sidebar-collapsible__inner { overflow: hidden; min-height: 0; display: flex; flex-direction: column; gap: 2px; }
.sidebar-collapsible__inner .sidebar__item { padding-left: 34px; }

/* Collapsed: collapsible becomes icon-only */
.sidebar--collapsed .sidebar-collapsible__trigger { justify-content: center; padding: 0; width: 32px; height: 32px; margin: 0 auto; }
.sidebar--collapsed .sidebar-collapsible__label,
.sidebar--collapsed .sidebar-collapsible__chevron { display: none; }
.sidebar--collapsed .sidebar-collapsible__content { display: none; }

